safeCss.css:
[data-ds-part="root"] {
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  letter-spacing: 0;
}
[data-ds-part="sidebar"] {
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  font-weight: 450;
  letter-spacing: 0;
}
[data-ds-part="header"] {
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  font-weight: 500;
}
[data-ds-part="home"] {
  font-family: "Iowan Old Style", Baskerville, "Songti SC", serif;
  line-height: 1.6;
}
[data-ds-part="home-hero"] {
  font-family: "Iowan Old Style", Baskerville, "Songti SC", serif;
  font-weight: 500;
  letter-spacing: -0.01em;
}
[data-ds-part="thread"] {
  font-family: "Iowan Old Style", Baskerville, "Songti SC", serif;
  line-height: 1.68;
}
[data-ds-part="message"] {
  font-family: "Iowan Old Style", Baskerville, "Songti SC", serif;
  line-height: 1.68;
}
[data-ds-part="composer"] {
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  font-size: 15px;
  line-height: 1.5;
}
[data-ds-part="composer-toolbar"] {
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  font-size: 13px;
}
[data-ds-part="dialog"] {
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  line-height: 1.5;
}
